export const SCRIPTS: Record<string, string> = {
	'agent-calls': "/**\n * Standalone invoke script for Agent Calls Demo\n *\n * Demonstrates: agent.run() for invoking agents, ctx.waitUntil() for background tasks\n * Shows the standalone pattern for agent invocation.\n *\n * Usage: bun run src/run/agent-calls.ts '{\"name\":\"World\"}'\n */\nimport { createAgentContext, getAgentContext } from '@agentuity/runtime';\nimport helloAgent from '../agent/hello/agent';\n\ninterface Input {\n\tname?: string;\n}\n\nconst input: Input = JSON.parse(process.argv[2] ?? '{}');\nconst name = input.name ?? 'Explorer';\n\nconst standaloneCtx = createAgentContext();\nstandaloneCtx.logger.info('Agent calls demo');\n\n// Must use invoke() to get proper execution context for waitUntil\nawait standaloneCtx.invoke(async () => {\n\tconst ctx = getAgentContext();\n\n\t// agent.run() invokes the agent and waits for result\n\tconst greeting = await helloAgent.run({ name });\n\n\t// ctx.waitUntil() schedules background work that runs after main execution\n\tlet backgroundCompleted = false;\n\tctx.waitUntil(\n\t\t(async () => {\n\t\t\t// Simulate async work (analytics, cleanup, etc)\n\t\t\tawait new Promise((resolve) => setTimeout(resolve, 100));\n\t\t\tbackgroundCompleted = true;\n\t\t})()\n\t);\n\n\t// Wait a moment for background task to complete (for demo purposes)\n\tawait new Promise((resolve) => setTimeout(resolve, 150));\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log('Agent Invocation (agent.run):');\n\tconsole.log(`  Input: { name: \"${name}\" }`);\n\tconsole.log(`  Result: ${JSON.stringify(greeting)}`);\n\tconsole.log('');\n\tconsole.log('Background Task (ctx.waitUntil):');\n\tconsole.log(`  Scheduled async work after main execution`);\n\tconsole.log(`  Status: ${backgroundCompleted ? 'completed' : 'still running'}`);\n});\n",
	'ai-gateway': "/**\n * Standalone run script for AI Gateway demo\n *\n * Route pattern demo - no corresponding agent exists.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: calling AI providers through Agentuity gateway\n * No API keys needed - uses AGENTUITY_SDK_KEY via gateway\n *\n * Usage: bun run src/run/ai-gateway.ts '{\"prompt\":\"Tell me a joke\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport { anthropic } from '@ai-sdk/anthropic';\nimport { openai } from '@ai-sdk/openai';\nimport { generateText } from 'ai';\n\ninterface Input {\n\tprompt?: string;\n}\n\nconst input: Input = JSON.parse(process.argv[2] ?? '{}');\nconst prompt = input.prompt ?? 'Explain AI agents in 1 sentence.';\n\nconst ctx = createAgentContext();\n\ntry {\n\t// Call both in parallel for speed\n\tctx.logger.info('Calling OpenAI and Anthropic in parallel...');\n\n\tconst [openaiResult, claudeResult] = await Promise.all([\n\t\tgenerateText({\n\t\t\tmodel: openai('gpt-5-nano'),\n\t\t\tprompt,\n\t\t}),\n\t\tgenerateText({\n\t\t\tmodel: anthropic('claude-haiku-4-5'),\n\t\t\tprompt,\n\t\t}),\n\t]);\n\n\tctx.logger.info('Both completed');\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Prompt: \"${prompt}\"`);\n\tconsole.log('');\n\tconsole.log('OpenAI (gpt-5-nano):');\n\tconsole.log(openaiResult.text);\n\tconsole.log('');\n\tconsole.log('Anthropic (claude-haiku-4-5):');\n\tconsole.log(claudeResult.text);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'chat': "/**\n * Standalone run script for Chat demo\n *\n * NOTE: Intentionally separate from src/agent/chat/agent.ts.\n * Uses simplified model (gpt-5-nano) without commands.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: Thread state and session state APIs\n * Shows the full state management API surface.\n *\n * Usage: bun run src/run/chat.ts '{\"message\":\"Hello!\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport { openai } from '@ai-sdk/openai';\nimport { generateText } from 'ai';\nimport agentuityDocs from '../agent/chat/agentuity-context.txt';\n\ninterface Message {\n\trole: 'user' | 'assistant';\n\tcontent: string;\n}\n\ninterface Input {\n\tmessage?: string;\n}\n\nconst input: Input = JSON.parse(process.argv[2] ?? '{}');\nconst message = input.message ?? 'What is Agentuity?';\n\nconst ctx = createAgentContext();\n\ntry {\n\t// Session state: per-request timing\n\tctx.session.state.set('requestStart', Date.now());\n\n\t// Thread state: persists across requests (empty on first run in sandbox)\n\tconst messages = ((await ctx.thread.state.get('messages')) as Message[]) ?? [];\n\tconst turnCount = ((await ctx.thread.state.get('turnCount')) as number) ?? 0;\n\tctx.logger.info('Thread state retrieved', {\n\t\tmessageCount: messages.length,\n\t\tturnCount,\n\t\tnote: messages.length === 0 ? 'empty (first run)' : 'has history',\n\t});\n\n\t// Generate response\n\tctx.logger.info('Generating response');\n\tconst { text } = await generateText({\n\t\tmodel: openai('gpt-5-nano'),\n\t\tsystem: `You are an Agentuity expert assistant. Keep responses concise (2-3 sentences).\n\n## Agentuity Documentation\n${agentuityDocs}`,\n\t\tmessages: [...messages, { role: 'user', content: message }],\n\t});\n\n\t// Update thread state with sliding window (max 50 messages)\n\tawait ctx.thread.state.push('messages', { role: 'user', content: message }, 50);\n\tawait ctx.thread.state.push('messages', { role: 'assistant', content: text }, 50);\n\tawait ctx.thread.state.set('turnCount', turnCount + 1);\n\tctx.logger.info('Thread state updated', { newTurnCount: turnCount + 1 });\n\n\t// Session state: check elapsed time\n\tconst elapsed = Date.now() - (ctx.session.state.get('requestStart') as number);\n\tctx.logger.info('Request completed', { elapsedMs: elapsed });\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`User: \"${message}\"`);\n\tconsole.log(`Assistant: \"${text}\"`);\n\tconsole.log(`Turn: ${turnCount + 1} (elapsed: ${elapsed}ms)`);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'cron': "/**\n * Standalone run script for Cron demo\n *\n * Route pattern demo - no corresponding agent exists.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: Simulating a cron job trigger\n * In the real world, cron jobs are triggered by the platform on schedule.\n * This simulates what happens when a cron job runs.\n *\n * Usage: bun run src/run/cron.ts '{}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\n\nconst ctx = createAgentContext();\nconst bucket = 'v1-ks-cron';\n\ntry {\n\tctx.logger.info('Hourly task running');\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log('=== Hourly Data Sync (Simulated) ===');\n\tconsole.log(`Triggered at: ${new Date().toISOString()}`);\n\tconsole.log('');\n\n\t// Simulate fetching external data\n\tconsole.log('Step 1: Fetching external data...');\n\tconst mockData = {\n\t\tlastUpdate: new Date().toISOString(),\n\t\trecordCount: Math.floor(Math.random() * 1000) + 100,\n\t\tsource: 'api.example.com',\n\t};\n\tconsole.log(`  Fetched ${mockData.recordCount} records from ${mockData.source}`);\n\tconsole.log('');\n\n\t// Cache the result in KV storage\n\tconsole.log('Step 2: Caching in KV storage...');\n\tawait ctx.kv.set(bucket, 'latest-sync', mockData, { ttl: 3600 });\n\tconsole.log(`  Cached to \"${bucket}/latest-sync\" (TTL: 1 hour)`);\n\tconsole.log('');\n\n\t// Verify the cache\n\tconst cached = await ctx.kv.get(bucket, 'latest-sync');\n\tconsole.log('Step 3: Verifying cache...');\n\tif (cached.exists) {\n\t\tconst data = cached.data as typeof mockData;\n\t\tconsole.log(`  Cache verified: ${data.recordCount} records`);\n\t} else {\n\t\tconsole.log('  Cache verification failed!');\n\t}\n\tconsole.log('');\n\n\t// Cleanup (demo only - real cron jobs would keep the cache)\n\tconsole.log('Step 4: Cleaning up (demo only)...');\n\tawait ctx.kv.delete(bucket, 'latest-sync');\n\tconsole.log(`  Deleted \"${bucket}/latest-sync\"`);\n\tconsole.log('');\n\n\tconsole.log('Cron job completed successfully');\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'durable-stream': "/**\n * Standalone run script for Durable Streams demo\n *\n * Route pattern demo - no corresponding agent exists.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: Creating a durable stream with a shareable URL\n * Writes content to the stream and shows the public URL.\n *\n * Usage: bun run src/run/durable-stream.ts '{\"content\":\"Hello world\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\n\ninterface Input {\n\tcontent?: string;\n}\n\nconst ctx = createAgentContext();\n\ntry {\n\tconst input: Input = JSON.parse(process.argv[2] ?? '{}');\n\tconst content =\n\t\tinput.content ?? 'This is a durable stream demo.\\nContent persists with a shareable URL.';\n\tctx.logger.info('Creating durable stream');\n\n\t// Create a durable stream\n\tconst streamName = `demo-${Date.now()}`;\n\tconst stream = await ctx.stream.create(streamName, {\n\t\tcontentType: 'text/plain',\n\t\tmetadata: { created: new Date().toISOString() },\n\t});\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Stream created: ${streamName}`);\n\tconsole.log(`Stream ID: ${stream.id}`);\n\tconsole.log('');\n\n\t// Write content\n\tawait stream.write(content);\n\tconsole.log('Content written:');\n\tconsole.log(`  \"${content.split('\\n')[0]}...\"`);\n\tconsole.log('');\n\n\t// Close the stream\n\tawait stream.close();\n\tconsole.log('Stream closed');\n\tconsole.log('');\n\n\t// The URL is shareable and permanent\n\tconsole.log('Public URL (shareable):');\n\tconsole.log(`  ${stream.url}`);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'evals': "/**\n * Standalone invoke script for Evals Demo\n *\n * Demonstrates: Running evaluations on agent output\n * Shows both a preset-style eval (completeness) and custom eval (factual claims)\n *\n * Usage: bun run src/run/evals.ts '{\"question\":\"What is TypeScript?\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport { openai } from '@ai-sdk/openai';\nimport { generateText } from 'ai';\nimport agentuityDocs from '../agent/chat/agentuity-context.txt';\n\ninterface Input {\n\tquestion?: string;\n}\n\n// Helper to extract JSON from LLM response (handles markdown code blocks)\nfunction parseJSON<T>(text: string, fallback: T): T {\n\ttry {\n\t\tconst jsonMatch = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/);\n\t\tconst jsonStr = jsonMatch && jsonMatch[1] ? jsonMatch[1].trim() : text.trim();\n\t\treturn JSON.parse(jsonStr);\n\t} catch {\n\t\treturn fallback;\n\t}\n}\n\nconst input: Input = JSON.parse(process.argv[2] ?? '{}');\nconst question = input.question ?? 'What is Agentuity and what are its main features?';\n\nconst ctx = createAgentContext();\n\nctx.logger.info('Running evals demo');\n\ntry {\n\t// Step 1: Generate the answer (with Agentuity context)\n\tconst { text: answer } = await generateText({\n\t\tmodel: openai('gpt-5-nano'),\n\t\tsystem: `You are an Agentuity expert. Answer questions based on this documentation:\n\n${agentuityDocs}`,\n\t\tprompt: question,\n\t});\n\n\t// Truncate answer for eval prompts\n\tconst truncatedAnswer = answer.slice(0, 500);\n\n\t// Step 2: Run both evals in PARALLEL (like ai-gateway.ts pattern)\n\tconst [completenessResult, factualResult] = await Promise.all([\n\t\tgenerateText({\n\t\t\tmodel: openai('gpt-5-nano'),\n\t\t\tprompt: `Rate 0-1 how completely this answer addresses the question. Return ONLY JSON: {\"score\": 0.85, \"reason\": \"brief reason\"}\n\nQ: \"${question}\"\nA: \"${truncatedAnswer}\"`,\n\t\t}).catch(() => null),\n\t\tgenerateText({\n\t\t\tmodel: openai('gpt-5-nano'),\n\t\t\tprompt: `Does this text contain factual claims? Return ONLY JSON: {\"containsFactualClaims\": true, \"reason\": \"brief reason\"}\n\n\"${truncatedAnswer}\"`,\n\t\t}).catch(() => null),\n\t]);\n\n\t// Parse results with fallbacks\n\tconst completeness = completenessResult\n\t\t? parseJSON(completenessResult.text, { score: 0.75, reason: 'Could not parse eval result' })\n\t\t: { score: 0.75, reason: 'Eval failed' };\n\n\tconst factual = factualResult\n\t\t? parseJSON(factualResult.text, {\n\t\t\t\tcontainsFactualClaims: true,\n\t\t\t\treason: 'Could not parse eval result',\n\t\t\t})\n\t\t: { containsFactualClaims: true, reason: 'Eval failed' };\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Question: \"${question}\"`);\n\tconsole.log('');\n\tconsole.log(`Answer: \"${answer.slice(0, 200)}${answer.length > 200 ? '...' : ''}\"`);\n\tconsole.log('');\n\tconsole.log('Evals:');\n\tconsole.log(\n\t\t`  answer-completeness: ${(completeness.score * 100).toFixed(0)}% - \"${completeness.reason}\"`\n\t);\n\tconsole.log(\n\t\t`  factual-claims: ${factual.containsFactualClaims ? 'Passed' : 'Failed'} - \"${factual.reason}\"`\n\t);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'handler-context': "/**\n * Standalone run script for Handler Context demo\n *\n * NOTE: Intentionally separate from src/agent/handler-context/agent.ts.\n * Exploratory demo showing ctx object, agent is more structured.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: Key AgentContext properties and methods\n * This exercises the ctx object to show what's available inside handlers.\n *\n * Usage: bun run src/run/handler-context.ts '{}'\n */\nimport { createAgentContext, getAgentContext } from '@agentuity/runtime';\n\nconst standaloneCtx = createAgentContext();\n\n// Wrap in invoke() - inside the callback, use getAgentContext() to get the\n// context with real IDs (the outer standaloneCtx still has \"pending\" IDs)\nawait standaloneCtx.invoke(async () => {\n\ttry {\n\t\t// Get the actual context from AsyncLocalStorage (has real sessionId/threadId)\n\t\tconst ctx = getAgentContext();\n\n\t\tconsole.log('---OUTPUT---');\n\t\tconsole.log('');\n\n\t\t// Identifiers\n\t\tconsole.log('Identifiers:');\n\t\tconsole.log(`  sessionId: ${ctx.sessionId}`);\n\t\tconsole.log(`  threadId: ${ctx.thread.id}`);\n\t\tconsole.log('');\n\n\t\t// Logger demonstration\n\t\tconsole.log('Logger (writes to trace, shown above):');\n\t\tctx.logger.info('Processing request', { userId: 'user-123' });\n\t\tctx.logger.debug('Debug details', { threadId: ctx.thread.id });\n\t\tctx.logger.warn('Example warning log');\n\t\tctx.logger.error('Example error log');\n\t\tconsole.log('  ctx.logger.info(), .debug(), .warn(), .error() available');\n\t\tconsole.log('');\n\n\t\t// Storage access demonstration\n\t\tconsole.log('Storage Access:');\n\t\tconsole.log('  ctx.kv - Key-Value storage');\n\t\tconsole.log('  ctx.vector - Vector storage');\n\t\tconsole.log('  ctx.objectstore - Object storage (S3)');\n\t\tconsole.log('');\n\n\t\t// Thread state demonstration\n\t\tconsole.log('Thread State (persists across requests):');\n\t\tawait ctx.thread.state.set('demo-key', { value: 'test' });\n\t\tconst stored = await ctx.thread.state.get('demo-key');\n\t\tconsole.log(`  set(\"demo-key\", {value: \"test\"})`);\n\t\tconsole.log(`  get(\"demo-key\") -> ${JSON.stringify(stored)}`);\n\t\tawait ctx.thread.state.delete('demo-key');\n\t\tconsole.log('  delete(\"demo-key\") - cleaned up');\n\t\tconsole.log('');\n\n\t\t// Session state demonstration\n\t\tconsole.log('Session State (per-request only):');\n\t\tconst timestamp = new Date().toISOString();\n\t\tctx.session.state.set('request-time', timestamp);\n\t\tconst requestTime = ctx.session.state.get('request-time');\n\t\tconsole.log(`  set(\"request-time\", \"${timestamp}\")`);\n\t\tconsole.log(`  get(\"request-time\") -> ${requestTime}`);\n\t} catch (error) {\n\t\tconsole.log('---OUTPUT---');\n\t\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n\t}\n});\n",
	'hello': "/**\n * Standalone invoke script for Hello Agent\n *\n * Uses ctx.invoke() with agent.run() pattern (SDK 0.1.14+)\n *\n * Usage: bun run src/run/hello.ts '{\"name\":\"World\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport helloAgent from '../agent/hello/agent';\n\nconst input = JSON.parse(process.argv[2] ?? '{\"name\":\"World\"}');\nconst ctx = createAgentContext();\n\ntry {\n\tctx.logger.info('Processing greeting', { name: input.name });\n\tconst result = await ctx.invoke(() => helloAgent.run(input));\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log(result);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'kv': "/**\n * Standalone run script for KV Storage demo\n *\n * NOTE: Intentionally separate from src/agent/kv/agent.ts.\n * Uses \"explorer-sandbox\" bucket with cleanup (delete) operations.\n * See src/run/README.md for architecture details.\n *\n * Shows direct SDK calls: set → get → delete\n * Uses unique keys per run for isolation\n *\n * Usage: bun run src/run/kv.ts '{}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\n\nconst ctx = createAgentContext();\n\n// Unique key prefix for this run (isolation)\nconst runId = Date.now().toString(36);\nconst bucket = 'explorer-sandbox';\nconst key = `${runId}:session-001`;\n\n// Sample session data to store\nconst sessionData = {\n\tvisitorId: 'visitor-abc123',\n\tlastActive: new Date().toISOString(),\n\tpreferences: { theme: 'dark' },\n};\n\ntry {\n\tctx.logger.info('Setting key');\n\n\t// SET - store data with TTL\n\tawait ctx.kv.set(bucket, key, sessionData, { ttl: 300 });\n\n\tctx.logger.info('Getting key');\n\n\t// GET - retrieve data\n\tconst result = await ctx.kv.get(bucket, key);\n\n\t// DELETE - cleanup (before OUTPUT so it shows in logs)\n\tawait ctx.kv.delete(bucket, key);\n\tctx.logger.info('Deleted key');\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Set: \"${key}\"`);\n\tconsole.log(`  visitorId: \"${sessionData.visitorId}\"`);\n\tconsole.log(`  theme: \"${sessionData.preferences.theme}\"`);\n\tconsole.log(`Get: ${result.exists ? 'found' : 'not found'}`);\n\tconsole.log(`Deleted: \"${key}\"`);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'model-arena': "/**\n * Standalone run script for Model Arena demo\n *\n * NOTE: Intentionally separate from src/agent/model-arena/agent.ts.\n * Uses different models than the agent.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: LLM-as-Judge pattern - two models compete, judge picks winner\n * Uses OpenAI vs Anthropic with OpenAI as judge\n *\n * Usage: bun run src/run/model-arena.ts '{\"prompt\":\"Write a haiku about coding\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport { anthropic } from '@ai-sdk/anthropic';\nimport { openai } from '@ai-sdk/openai';\nimport { generateText } from 'ai';\n\ninterface Input {\n\tprompt?: string;\n}\n\ninterface Judgment {\n\twinner: 'model-a' | 'model-b';\n\treasoning: string;\n\tscores: {\n\t\tcreativity: number;\n\t\tclarity: number;\n\t};\n}\n\nfunction parseJSON<T>(text: string, fallback: T): T {\n\ttry {\n\t\tconst jsonMatch = text.match(/```(?:json)?\\s*([\\s\\S]*?)```/);\n\t\tconst jsonStr = jsonMatch && jsonMatch[1] ? jsonMatch[1].trim() : text.trim();\n\t\treturn JSON.parse(jsonStr);\n\t} catch {\n\t\treturn fallback;\n\t}\n}\n\nconst input: Input = JSON.parse(process.argv[2] ?? '{}');\nconst userPrompt = input.prompt ?? 'Write a creative one-liner about programming.';\n\nconst ctx = createAgentContext();\n\n// Collect all output, print at the very end\nconst output: string[] = [];\n\ntry {\n\t// Generate competing responses in parallel (no logging during execution)\n\tconst [responseA, responseB] = await Promise.all([\n\t\tgenerateText({\n\t\t\tmodel: openai('gpt-5-nano'),\n\t\t\tprompt: userPrompt,\n\t\t}),\n\t\tgenerateText({\n\t\t\tmodel: anthropic('claude-haiku-4-5'),\n\t\t\tprompt: userPrompt,\n\t\t}),\n\t]);\n\n\t// Use OpenAI for judging with manual JSON parsing\n\tconst judgeResult = await generateText({\n\t\tmodel: openai('gpt-5-nano'),\n\t\tprompt: `Compare these responses and pick a winner. Return ONLY JSON:\n{\"winner\": \"model-a\" or \"model-b\", \"reasoning\": \"brief reason\", \"scores\": {\"creativity\": 0.0-1.0, \"clarity\": 0.0-1.0}}\n\nModel A: ${responseA.text.slice(0, 200)}\nModel B: ${responseB.text.slice(0, 200)}`,\n\t});\n\n\tconst judgment = parseJSON<Judgment>(judgeResult.text, {\n\t\twinner: 'model-a',\n\t\treasoning: 'Could not parse judge response',\n\t\tscores: { creativity: 0.5, clarity: 0.5 },\n\t});\n\n\t// Buffer all output (matches reference code style)\n\toutput.push(`[INFO] Model A (OpenAI gpt-5-nano): \"${responseA.text}\"`);\n\toutput.push('');\n\toutput.push(`[INFO] Model B (Anthropic claude-haiku-4-5): \"${responseB.text}\"`);\n\toutput.push('');\n\toutput.push(`[INFO] Judge result {\"winner\":\"${judgment.winner}\"}`);\n\toutput.push(`[INFO] Scores {\"creativity\":${judgment.scores.creativity},\"clarity\":${judgment.scores.clarity}}`);\n\toutput.push(`[INFO] Reasoning: ${judgment.reasoning}`);\n} catch (error) {\n\toutput.push(`[ERROR] ${error instanceof Error ? error.message : String(error)}`);\n}\n\n// Print everything at once at the very end\nconsole.log(output.join('\\n'));\n",
	'objectstore': "/**\n * Standalone run script for Object Storage demo\n *\n * NOTE: Intentionally separate from src/agent/objectstore/agent.ts.\n * Uses dynamic filenames with cleanup (delete) operations.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: Write → Read flow with Bun's S3 API\n * Credentials are auto-injected by Agentuity runtime.\n *\n * Usage: bun run src/run/objectstore.ts '{}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport { s3 } from 'bun';\n\nconst ctx = createAgentContext();\n\nconst filename = `demo-${Date.now()}.txt`;\nconst content = `Hello from Object Storage!\\nTimestamp: ${new Date().toISOString()}`;\n\ntry {\n\tctx.logger.info('Writing file');\n\n\t// Write a file\n\tconst file = s3.file(filename);\n\tawait file.write(content);\n\n\tctx.logger.info('Reading file');\n\n\t// Read it back\n\tconst readContent = await file.text();\n\n\t// Check existence\n\tconst exists = await file.exists();\n\n\tctx.logger.info('Deleting file');\n\n\t// Delete\n\tawait file.delete();\n\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Write: \"${filename}\"`);\n\tconsole.log(`  Content: ${content.split('\\n')[0]}...`);\n\tconsole.log(`Read: \"${filename}\"`);\n\tconsole.log(`  Content: ${readContent.split('\\n')[0]}...`);\n\tconsole.log(`Exists: ${exists}`);\n\tconsole.log(`Deleted: \"${filename}\"`);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'sse-stream': "/**\n * Standalone run script for SSE Stream demo\n *\n * Route pattern demo - no corresponding agent exists.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: SSE-style streaming using streamText\n * Note: Sandbox buffers stdout, so output appears all at once.\n * In a real server with sse() middleware, tokens would stream via SSE events.\n *\n * Usage: bun run src/run/sse-stream.ts '{\"prompt\":\"Tell me a story\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport { openai } from '@ai-sdk/openai';\nimport { streamText } from 'ai';\n\ninterface Input {\n\tprompt?: string;\n}\n\nconst ctx = createAgentContext();\n\ntry {\n\tconst input: Input = JSON.parse(process.argv[2] ?? '{}');\n\tconst prompt = input.prompt ?? 'Explain what Server-Sent Events are in 2-3 sentences.';\n\tctx.logger.info('SSE stream started', { prompt });\n\tconst { textStream } = streamText({\n\t\tmodel: openai('gpt-5-nano'),\n\t\tprompt,\n\t});\n\n\t// Collect streamed tokens (sandbox buffers stdout anyway)\n\tlet fullText = '';\n\tlet tokenCount = 0;\n\tfor await (const chunk of textStream) {\n\t\tfullText += chunk;\n\t\ttokenCount++;\n\t}\n\n\t// Output everything at once\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Prompt: \"${prompt}\"`);\n\tconsole.log('');\n\tconsole.log(fullText);\n\tconsole.log('');\n\tconsole.log(`[Streamed ${tokenCount} SSE events]`);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'streaming': "/**\n * Standalone run script for Streaming demo\n *\n * Route pattern demo - no corresponding agent exists.\n * See src/run/README.md for architecture details.\n *\n * Demonstrates: Raw text streaming using streamText\n * Note: Sandbox buffers stdout, so output appears all at once.\n * In a real server, tokens would stream to the client in real-time.\n *\n * Usage: bun run src/run/streaming.ts '{\"prompt\":\"Tell me a story\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\nimport { openai } from '@ai-sdk/openai';\nimport { streamText } from 'ai';\n\ninterface Input {\n\tprompt?: string;\n}\n\nconst ctx = createAgentContext();\n\ntry {\n\tconst input: Input = JSON.parse(process.argv[2] ?? '{}');\n\tconst prompt = input.prompt ?? 'Write a short poem about AI.';\n\tctx.logger.info('Streaming started', { prompt });\n\tconst { textStream } = streamText({\n\t\tmodel: openai('gpt-5-nano'),\n\t\tprompt,\n\t});\n\n\t// Collect streamed tokens (sandbox buffers stdout anyway)\n\tlet fullText = '';\n\tlet tokenCount = 0;\n\tfor await (const chunk of textStream) {\n\t\tfullText += chunk;\n\t\ttokenCount++;\n\t}\n\n\t// Output everything at once\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Prompt: \"${prompt}\"`);\n\tconsole.log('');\n\tconsole.log(fullText);\n\tconsole.log('');\n\tconsole.log(`[Streamed ${tokenCount} tokens]`);\n} catch (error) {\n\tconsole.log('---OUTPUT---');\n\tconsole.log(`Error: ${error instanceof Error ? error.message : String(error)}`);\n}\n",
	'vector': "/**\n * Standalone run script for Vector Search demo\n *\n * NOTE: Intentionally separate from src/agent/vector/agent.ts.\n * Uses \"explorer-sandbox\" namespace with cleanup (delete) operations.\n * See src/run/README.md for architecture details.\n *\n * Shows direct SDK calls: upsert → search → cleanup\n * Uses unique keys per run for isolation\n *\n * Usage: bun run src/run/vector.ts '{\"query\":\"comfortable chair\"}'\n */\nimport { createAgentContext } from '@agentuity/runtime';\n\nconst input = JSON.parse(process.argv[2] ?? '{}');\nconst query = input.query ?? 'comfortable chair';\nconst ctx = createAgentContext();\n\n// Unique key prefix for this run (isolation)\nconst runId = Date.now().toString(36);\nconst namespace = 'explorer-sandbox';\n\n// Sample product to upsert\nconst product = {\n\tsku: `${runId}:chair-001`,\n\tname: 'ErgoMax Pro Chair',\n\tprice: 549,\n};\n\n// UPSERT: document text is auto-embedded\nawait ctx.vector.upsert(namespace, {\n\tkey: product.sku,\n\tdocument: `${product.name}: Premium ergonomic office chair with lumbar support`,\n\tmetadata: product,\n});\n\n// SEARCH: finds by meaning (\"comfortable\" matches \"ergonomic\")\nconst results = await ctx.vector.search(namespace, {\n\tquery,\n\tlimit: 3,\n\tsimilarity: 0.3,\n});\n\n// Results include similarity scores and metadata\nfor (const result of results) {\n\tctx.logger.info('Match found', {\n\t\tname: result.metadata?.name,\n\t\tprice: result.metadata?.price,\n\t\tsimilarity: result.similarity.toFixed(2),\n\t});\n}\n\n// CLEANUP: delete the unique key\nawait ctx.vector.delete(namespace, product.sku);\nctx.logger.info('Cleaned up', { sku: product.sku });\n\nconsole.log('---OUTPUT---');\nconsole.log(`Upserted: \"${product.name}\" (${product.sku})`);\nconsole.log(`Searched: \"${query}\"`);\nconsole.log(`Found: ${results.length} match(es)`);\nfor (const r of results) {\n\tconsole.log(\n\t\t`  - \"${r.metadata?.name}\" ($${r.metadata?.price}) - ${Math.round(r.similarity * 100)}%`\n\t);\n}\n",
};

